    "corpo": [
      "A aplicação da lei penal militar no tempo segue os mesmos princípios fundamentais já estudados em Direito Penal comum: legalidade, anterioridade, e retroatividade da lei mais benéfica (a lei penal militar mais gravosa não retroage; a mais benéfica sempre retroage, mesmo após o trânsito em julgado). O Código Penal Militar adota a teoria da atividade para definir o tempo do crime: considera-se praticado o crime no momento da ação ou omissão, ainda que outro seja o momento do resultado.",
      "Para o lugar do crime, o CPM adota a teoria da ubiquidade (mista): considera-se praticado o crime tanto no lugar em que ocorreu a ação ou omissão, no todo ou em parte, quanto onde se produziu ou deveria produzir-se o resultado — a mesma lógica já estudada na aplicação da lei penal comum no espaço.",
      "Um ponto de atenção específico do Direito Penal Militar é a aplicação da lei penal militar a fatos ocorridos fora do território nacional, em hipóteses específicas envolvendo forças brasileiras em operações no exterior (missões de paz, por exemplo) — situação de aplicação extraterritorial da lei penal militar brasileira, distinta das hipóteses gerais de extraterritorialidade do Código Penal comum."
    ],
