      "O Código Penal Militar prevê excludentes de ilicitude semelhantes às do Direito Penal comum: estado de necessidade, legítima defesa, estrito cumprimento do dever legal e exercício regular de direito — com aplicação e requisitos estruturalmente parecidos aos já estudados, mas com maior relevância prática para o estrito cumprimento do dever legal, dada a natureza da atividade militar (missões que envolvem o uso de força e restrição de direitos de terceiros).",
      "Uma excludente de culpabilidade com tratamento específico e de grande relevância no contexto militar é a obediência hierárquica: o subordinado que cumpre ordem de superior hierárquico competente, não manifestamente ilegal, tem sua culpabilidade excluída, respondendo apenas o autor da ordem — segue a mesma lógica geral já estudada em Direito Penal comum (a ordem manifestamente ilegal não exclui a responsabilidade de quem a executa).",
      "Quanto à culpabilidade, o CPM também prevê a inimputabilidade por doença mental ou desenvolvimento mental incompleto/retardado, com estrutura semelhante à do Código Penal comum — mas a avaliação da capacidade de discernimento e autodeterminação no contexto militar considera também as particularidades da vida na caserna e da disciplina militar aplicável."
