      "Motim e revolta são crimes propriamente militares que envolvem a reunião de militares em desobediência coletiva à autoridade — a diferença central entre eles está no uso ou não de armas: motim é a reunião de militares em desobediência ostensiva à ordem, sem emprego de armas; revolta é a mesma conduta, mas com emprego de arma, o que a torna significativamente mais grave em razão do risco concreto à vida e à integridade física envolvido.",
      "Aliciação para motim ou revolta é crime autônomo, que pune quem incita ou tenta convencer outros militares a participar dessas condutas, mesmo que o motim/revolta não chegue a se consumar — reconhece a gravidade do próprio ato de instigação à quebra da disciplina coletiva. Violência contra superior e violência contra inferior são crimes específicos que punem a agressão física dentro da relação hierárquica, com tratamento penal diferenciado conforme a direção da violência (a violência contra superior tende a ser tratada com maior gravidade, dada a proteção reforçada à hierarquia).",
      "Desrespeito a superior e recusa de obediência são crimes de menor gravidade que motim/revolta, mas também protegem a disciplina: desrespeitar superior (ofender sua dignidade ou decoro) e recusar cumprir ordem direta de superior (sem chegar à desobediência coletiva armada do motim/revolta) já configuram infrações penais militares específicas, mesmo em situações individuais e pontuais, sem a dimensão coletiva do motim."
