      "Diversos crimes propriamente militares protegem a correta execução do serviço, tipificando condutas que comprometem funções específicas de vigilância, segurança e prontidão: abandono de posto (afastar-se, sem ordem superior, do lugar de serviço que lhe tenha sido designado, mesmo que por curto período), dormir em serviço (adormecer o militar quando em serviço, comprometendo a vigilância que deveria exercer), e embriaguez em serviço (apresentar-se ou permanecer embriagado durante o exercício de função militar).",
      "Esses crimes, embora de gravidade variável conforme a função específica comprometida e o contexto (não é a mesma coisa abandonar um posto administrativo rotineiro ou um posto de vigilância em operação de risco), compartilham a mesma lógica de proteção: garantir que o militar cumpra efetivamente as funções de prontidão e vigilância que lhe foram atribuídas, já que falhas nesse tipo de função podem comprometer a segurança de toda a operação ou instalação.",
      "Retenção indevida (deixar de cumprir intimação ou requisição legal de autoridade competente, ou retardar indevidamente a entrega de documento ou objeto sob sua guarda funcional) e omissão de eficiência (deixar de exercer, com a devida diligência, atribuição prevista em regulamento, comprometendo a eficiência do serviço) completam esse grupo de crimes voltados à correta execução das funções militares cotidianas."
