    "corpo": [
      "Assim como o Código Penal comum protege a Administração Pública em geral, o Código Penal Militar prevê crimes específicos para proteger a administração militar: peculato militar (apropriar-se o militar de dinheiro, valor ou bem móvel, público ou particular, de que tem posse em razão do cargo/função militar, ou desviá-lo em proveito próprio ou alheio) e corrupção militar (solicitar ou receber vantagem indevida, ou aceitar promessa de vantagem, em razão de função militar) — com estrutura muito semelhante aos crimes equivalentes já estudados em Direito Penal comum.",
      "Falsificação de documento militar (falsificar, no todo ou em parte, documento público ou particular de natureza militar, ou alterar documento militar verdadeiro) protege a fé pública especificamente no contexto da documentação militar (guias, atestados, certidões e demais documentos da administração castrense) — segue lógica semelhante à falsificação de documentos do Direito Penal comum.",
      "Prevaricação militar (deixar o militar de praticar, indevidamente, ato de ofício, ou praticá-lo contra disposição expressa de lei, para satisfazer interesse ou sentimento pessoal) também guarda estreita semelhança com a prevaricação do Código Penal comum, adaptada ao contexto de funções e obrigações especificamente militares — reforçando que boa parte da lógica dos crimes contra a administração militar é uma adaptação, ao contexto castrense, dos princípios já estudados para a Administração Pública em geral."
    ],
    "pontosChave": [
      "Peculato e corrupção militar seguem estrutura muito semelhante aos crimes equivalentes do Direito Penal comum, adaptados ao contexto militar.",
      "Falsificação de documento militar protege especificamente a fé pública da documentação castrense.",
      "Prevaricação militar mantém a mesma lógica da prevaricação comum: deixar de agir (ou agir contra a lei) por interesse pessoal."
    ],
