    "corpo": [
      "O Código Penal Militar prevê como penas principais: morte (aplicável exclusivamente em tempo de guerra, conforme hipóteses taxativamente previstas, sendo executada por fuzilamento), reclusão, detenção, e outras penas específicas do contexto militar (como impedimento, suspensão do exercício do posto, e reforma). A pena de morte em tempo de guerra é uma peculiaridade exclusiva do Direito Penal Militar, sem equivalente no Direito Penal comum, e sua aplicação é excepcional, prevista apenas para os crimes militares mais graves cometidos nesse contexto específico.",
      "Reclusão e detenção militar seguem lógica semelhante às penas equivalentes do Direito Penal comum quanto à gravidade relativa (reclusão para crimes mais graves, detenção para os de menor gravidade), mas o cumprimento se dá em estabelecimento penal militar específico, sob regime disciplinar castrense, distinto do sistema penitenciário comum.",
      "Penas acessórias específicas do contexto militar incluem a perda de posto e patente (para oficiais condenados a determinadas penas) e a indignidade para o oficialato (impedimento de exercer função de oficial, decorrente de condenação por certos crimes que revelem incompatibilidade com os valores da hierarquia e disciplina militares) — refletindo a preocupação do Direito Penal Militar não apenas com a punição individual, mas com a manutenção da integridade e credibilidade da própria instituição castrense."
    ],
